def stable_unique(items):
    """Return a list of hashable values from items, preserving first occurrence order."""
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def frequencies(items):
    """Return a dict mapping each hashable value in items to its occurrence count."""
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts


def chunked(items, size):
    """Split items into chunks of the given size. Raise ValueError if size <= 0."""
    if size <= 0:
        raise ValueError("size must be positive")
    result = []
    for i in range(0, len(items), size):
        result.append(items[i:i + size])
    return result


def running_totals(numbers):
    """Return a list of cumulative sums of numbers."""
    result = []
    total = 0
    for num in numbers:
        total += num
        result.append(total)
    return result


def merge_intervals(intervals):
    """Merge overlapping or touching intervals and return sorted non-overlapping intervals."""
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])
    return merged


def lower_bound(values, target):
    """Return the first index in the sorted list values where value >= target, or len(values)."""
    lo = 0
    hi = len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def rotate_right(items, k):
    """Return a new list rotated right by k modulo its length. Negative k rotates left."""
    if not items:
        return []
    n = len(items)
    k = k % n
    if k == 0:
        return list(items)
    return items[-k:] + items[:-k]


def moving_average(numbers, window):
    """Return the moving averages of complete consecutive windows using a sliding window."""
    if window <= 0:
        raise ValueError("window must be positive")
    n = len(numbers)
    if window > n:
        return []
    result = []
    window_sum = sum(numbers[:window])
    result.append(window_sum / window)
    for i in range(window, n):
        window_sum += numbers[i] - numbers[i - window]
        result.append(window_sum / window)
    return result

class TTLCache:
    """A cache with time-to-live expiration and LRU eviction."""

    def __init__(self, capacity):
        """Initialize the cache with a positive integer capacity."""
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self.capacity = capacity
        self._data = {}

    def put(self, key, value, now, ttl):
        """Insert or replace a key-value pair with a TTL, evicting LRU if needed."""
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.purge(now)
        if key in self._data:
            del self._data[key]
        self._data[key] = (value, now + ttl)
        if len(self._data) > self.capacity:
            oldest_key = next(iter(self._data))
            del self._data[oldest_key]

    def get(self, key, now, default=None):
        """Return the value for key if not expired, marking it as most recently used."""
        self.purge(now)
        if key not in self._data:
            return default
        value, expires_at = self._data[key]
        del self._data[key]
        self._data[key] = (value, expires_at)
        return value

    def delete(self, key):
        """Remove a key from the cache if present, returning True if removed."""
        if key in self._data:
            del self._data[key]
            return True
        return False

    def purge(self, now):
        """Remove all entries expiring at or before now, returning the count removed."""
        to_remove = [k for k, (_, expires_at) in self._data.items() if expires_at <= now]
        for k in to_remove:
            del self._data[k]
        return len(to_remove)

    def size(self, now):
        """Return the number of live (non-expired) entries after purging."""
        self.purge(now)
        return len(self._data)

    def clear(self):
        """Remove all entries from the cache."""
        self._data.clear()

